<template><div class="page"><h2 class="page-title">设置储蓄目标</h2><p class="muted">收入由用户录入，不使用微信流入自动代替工资。</p><div class="card section"><el-form label-position="top" :model="form"><div class="grid"><el-form-item label="当前存款（元）"><el-input v-model="form.current"/></el-form-item><el-form-item label="目标存款（元）"><el-input v-model="form.target"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.start" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="目标日期"><el-date-picker v-model="form.end" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="固定月收入（元）"><el-input v-model="form.income"/></el-form-item></div><el-button type="primary" :loading="saving" @click="create">保存目标</el-button></el-form></div><div v-if="goalId" class="card section"><h3>分类预算约束</h3><el-alert title="最低预算是基于用户确认的规划约束，不是系统认定的最低生活标准。" type="info" :closable="false"/><el-table :data="constraints"><el-table-column prop="name" label="类别"/><el-table-column label="最低周预算（元）"><template #default="s"><el-input v-model="s.row.minimum"/></template></el-table-column><el-table-column label="最高预算（可选）"><template #default="s"><el-input v-model="s.row.maximum"/></template></el-table-column><el-table-column label="固定"><template #default="s"><el-switch v-model="s.row.fixed" @change="s.row.maximum=s.row.fixed?s.row.minimum:s.row.maximum"/></template></el-table-column><el-table-column label="可调整程度"><template #default="s"><el-select v-model="s.row.adjustability" :disabled="s.row.fixed"><el-option v-for="o in adjustabilityOptions" :key="o.value" v-bind="o"/></el-select></template></el-table-column></el-table><el-button class="section" type="primary" @click="saveConstraints">保存约束</el-button></div></div></template>
<script setup>
import { onMounted,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { yuanToMinor } from '../utils/money.js';import { adjustabilityOptions,validateGoal } from '../utils/forms.js'
const today=new Date().toISOString().slice(0,10);const next=new Date(Date.now()+180*86400000).toISOString().slice(0,10);const form=reactive({current:'5000',target:'12000',start:today,end:next,income:'3000'});const categories=ref([]),constraints=ref([]),goalId=ref(),saving=ref(false)
onMounted(async()=>{categories.value=(await api.get('/categories')).items;constraints.value=categories.value.map(c=>({category_code:c.code,name:c.name,minimum:'0',maximum:'',fixed:false,adjustability:'medium'}))})
async function create(){let current,target,income;try{current=yuanToMinor(form.current);target=yuanToMinor(form.target);income=yuanToMinor(form.income||'0')}catch(e){return ElMessage.error(e.message)}const err=validateGoal({start_date:form.start,target_date:form.end,current_savings_minor:current,target_savings_minor:target});if(err)return ElMessage.error(err);saving.value=true;try{const r=await api.post('/goals',{current_savings_minor:current,start_date:form.start,target_date:form.end,target_savings_minor:target,income_assumptions:[{frequency:'monthly',amount_minor:income,start_date:form.start,end_date:form.end,expected_day:10}]});goalId.value=r.id;ElMessage.success('目标已保存，请确认分类约束')}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
async function saveConstraints(){try{await api.put(`/goals/${goalId.value}/constraints`,{constraints:constraints.value.map(x=>({category_code:x.category_code,minimum_budget_minor:yuanToMinor(x.minimum||'0'),maximum_budget_minor:x.maximum===''?null:yuanToMinor(x.maximum),is_fixed:x.fixed,adjustability:x.fixed?'none':x.adjustability}))});ElMessage.success('约束已保存，可以生成预算')}catch(e){ElMessage.error(e.message)}}
</script>
